import{_ as a,o as r,c as i,ag as e}from"./chunks/framework.ePeAWSvT.js";const o="/images/voice-recording-01.png",l="/images/voice-recording-02.png",s="/images/voice-recording-03.png",d="/images/voice-recording-04.png",n="/images/voice-recording-05.png",x=JSON.parse('{"title":"语音速记","description":"","frontmatter":{},"headers":[],"relativePath":"voice/recording.md","filePath":"voice/recording.md","lastUpdated":null}'),c={name:"voice/recording.md"};function h(p,t,g,u,m,_){return r(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="语音速记" tabindex="-1">语音速记 <a class="header-anchor" href="#语音速记" aria-label="Permalink to &quot;语音速记&quot;">​</a></h1><blockquote><p>🎙️ 懒得打字？说出来就行！</p></blockquote><p>AI 实时转文字，60 分钟超长录音 + 27 种方言精准识别，让灵感一开口就被记录、润色。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>灵感速记</strong>：走在路上、地铁里突然冒出的想法，用语音捕捉，自动转正文、加标点</li><li><strong>语音日记 / 随笔</strong>：日常所思所感直接说出来，AI 润色成完整段落，省去打字</li><li><strong>待办 &amp; 计划清单</strong>：边做事边说出任务，转写后自动归为条目，易查易改</li><li><strong>学习复盘</strong>：朗读知识点或总结，实时文字稿方便后期整理与背诵</li><li><strong>旅行 / 观察记录</strong>：旅行途中或街头速写，用声音留痕，回头就是一篇流畅游记</li></ul><h2 id="我们的特色" tabindex="-1">我们的特色 <a class="header-anchor" href="#我们的特色" aria-label="Permalink to &quot;我们的特色&quot;">​</a></h2><ul><li><strong>文本润色</strong>：独家调教的润色语音风格，让润色后的文字效果不再是 AI 味儿</li><li><strong>方言/多语言</strong>：内置 27 种方言模型，普通话、粤语、川渝话等自由切换</li><li><strong>专业词库</strong>：AI 智能分析热词，同时可自定义行业术语，提高识别准确性</li></ul><div class="tip custom-block"><p class="custom-block-title">27种方言支持</p><p>上海话、四川话、武汉话、贵阳话、昆明话、西安话、郑州话、太原话、兰州话、银川话、西宁话、南京话、合肥话、南昌话、长沙话、苏州话、杭州话、济南话、天津话、石家庄话、黑龙江话、吉林话、辽宁话、闽南语、客家话、粤语、南宁话。</p></div><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><ol><li>打开 App，点击首页底部录音按钮，「长按」或短按选择「语音速记」</li><li>首次使用时，授权麦克风权限并点击「开始录音」</li><li>开始录制后，录制页面会有实时转录的文字展示出来，点击「完成」结束录音</li><li>录制过程中，可以点击右上角「语音词库」，自定义专业名词，提高识别准确率</li><li>录音完成后，AI 会自动润色转写文字、智能分段与标点纠正</li></ol><h2 id="实用小技巧" tabindex="-1">实用小技巧 <a class="header-anchor" href="#实用小技巧" aria-label="Permalink to &quot;实用小技巧&quot;">​</a></h2><ul><li>锁屏或切到后台，录音不中断</li><li>无网环境（地铁、隧道等）先本地缓存，恢复网络后自动上传同步</li></ul><h2 id="录制时长" tabindex="-1">录制时长 <a class="header-anchor" href="#录制时长" aria-label="Permalink to &quot;录制时长&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户类型</th><th>单次时长</th><th>次数限制</th></tr></thead><tbody><tr><td>普通用户</td><td>10 分钟</td><td>不限</td></tr><tr><td>PRO会员</td><td>60 分钟</td><td>不限</td></tr></tbody></table><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+o+'" alt="语音速记入口" style="width:180px;border-radius:8px;"><img src="'+l+'" alt="录音界面" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="转写结果" style="width:180px;border-radius:8px;"><img src="'+d+'" alt="词库设置" style="width:180px;border-radius:8px;"><img src="'+n+'" alt="笔记详情" style="width:180px;border-radius:8px;"></div>',16)])])}const f=a(c,[["render",h]]);export{x as __pageData,f as default};
